function M.project(room,x,y,z)
 local c=M.rooms[room];local m=c.m
 local w=m[4][1]*x+m[4][2]*y+m[4][3]*z+m[4][4]
 local sx=(m[1][1]*x+m[1][2]*y+m[1][3]*z+m[1][4])/w
 local sy=(m[2][1]*x+m[2][2]*y+m[2][3]*z+m[2][4])/w
 local v=c.view
 local depth=-(v[3][1]*x+v[3][2]*y+v[3][3]*z+v[3][4])
 return (sx+1)*240,(1-sy)*135,depth
end
function M.ground(room,x,y)
 local m=M.rooms[room].m;local u,v=x/240-1,1-y/135
 local a,b=m[1][1]-u*m[4][1],m[1][2]-u*m[4][2]
 local c,d=m[2][1]-v*m[4][1],m[2][2]-v*m[4][2]
 local e,f=u*m[4][4]-m[1][4],v*m[4][4]-m[2][4]
 local det=a*d-b*c
 if math.abs(det)<1e-9 then return nil end
 return (e*d-b*f)/det,(a*f-e*c)/det
end
function M.basis(room)
 local v=M.rooms[room].view
 local rx,ry=v[1][1],v[1][2];local r=math.sqrt(rx*rx+ry*ry)
 local ax,ay=-v[3][1],-v[3][2];local a=math.sqrt(ax*ax+ay*ay)
 return rx/r,ry/r,ax/a,ay/a
end
function M.facing(room,dx,dy)
 local rx,ry,ax,ay=M.basis(room)
 return math.atan(-(dx*rx+dy*ry),-(dx*ax+dy*ay))
end
function M.vertex(room,sx,sy,ax,ay,az,facing)
 local gx,gy=M.ground(room,sx,sy)
 local rx,ry,dx,dy=M.basis(room)
 local s,c=math.sin(facing),math.cos(facing)
 local factor=1.8/1.852
 local right,away=(ax*c+az*s)*factor,(az*c-ax*s)*factor
 local x,y,depth=M.project(room,gx+rx*right+dx*away,gy+ry*right+dy*away,ay*factor)
 return {math.floor(x+.5),math.floor(y+.5),depth}
end
